-- FiNN core schema.
--
-- FiNN is a manual record-keeping app: every row below is something the user
-- recorded. Nothing here moves real money.
--
-- Conventions
-- * Money is an integer number of paise (bigint). Never floating point.
-- * Calendar dates are `date` (the user's local calendar); instants are
--   timestamptz.
-- * Record ids are generated by the client (`prefix_<time36><rand36>`, or
--   fixed ids such as `cat_sys_emi` for standard categories), so they are
--   unique per user only: every primary key is (user_id, id) and every
--   reference is a composite foreign key, which also guarantees that a record
--   can only point at records of the same user.
-- * Derived figures (balances, budget spending, goal savings, loan
--   outstanding, alerts, net worth) are NOT stored. They are computed from
--   these records by the API, following docs/FINANCIAL_MODEL.md.
-- * `version` implements optimistic concurrency (compared by the API).
-- * `sync_seq` is a per-database monotonic change counter used by
--   GET /api/v1/sync. Deletions leave a row in `deleted_records`.

create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated, service_role;

create sequence public.finn_sync_seq as bigint;
grant usage, select on sequence public.finn_sync_seq to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Identity: profile (directory entry + financial starting point)
-- ---------------------------------------------------------------------------

create table public.profiles (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- Public directory entry (searchable by other FiNN users).
  display_name text not null check (char_length(display_name) between 1 and 40),
  handle text not null check (handle ~ '^@[a-z0-9._]{3,30}$'),
  phone_hint text check (phone_hint is null or char_length(phone_hint) <= 12),
  -- FinancialProfile. Null until onboarding sets an opening balance.
  opening_paise bigint check (opening_paise is null or opening_paise >= 0),
  opening_date date,
  monthly_income_estimate_paise bigint check (monthly_income_estimate_paise is null or monthly_income_estimate_paise > 0),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  constraint profiles_opening_pair check ((opening_paise is null) = (opening_date is null))
);
create unique index profiles_handle_key on public.profiles (lower(handle));
comment on table public.profiles is 'One row per FiNN user: directory entry (name, handle, phone hint) and FinancialProfile (opening balance/date). Financial fields are null until onboarding.';

-- User preferences that change financial figures or alerts. Purely visual
-- settings (theme, motion, haptics, balance masking) stay on the device.
create table public.user_preferences (
  user_id uuid primary key references auth.users (id) on delete cascade,
  month_start_day smallint not null default 1 check (month_start_day between 1 and 28),
  emi_reminder_days smallint not null default 5 check (emi_reminder_days between 0 and 30),
  subscription_reminder_days smallint not null default 3 check (subscription_reminder_days between 0 and 30),
  low_emergency_coverage_months smallint not null default 3 check (low_emergency_coverage_months between 1 and 24),
  default_budget_warning_bps integer not null default 8000 check (default_budget_warning_bps between 5000 and 9500),
  disabled_alert_types text[] not null default '{}',
  -- IANA zone used to decide "today" and month boundaries on the server.
  time_zone text not null default 'Asia/Kolkata' check (char_length(time_zone) between 1 and 64),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq')
);
comment on table public.user_preferences is 'Preferences that affect calculations and alerts (month start day, reminder windows, thresholds, time zone).';

-- ---------------------------------------------------------------------------
-- Categories and transactions (the cash ledger)
-- ---------------------------------------------------------------------------

create table public.categories (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  name text not null check (char_length(name) between 2 and 30),
  type text not null check (type in ('income', 'expense')),
  icon_key text not null check (char_length(icon_key) between 1 and 40),
  color_index smallint not null check (color_index between 0 and 63),
  description text not null default '' check (char_length(description) <= 120),
  is_system boolean not null default false,
  is_archived boolean not null default false,
  is_essential boolean not null default false,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  -- Needed by composite FKs that also pin the category type.
  unique (user_id, id, type)
);
comment on table public.categories is 'Transaction categories (standard, custom and system). System categories are used by linked transactions (EMIs, settlements, disbursements).';

create table public.transactions (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  type text not null check (type in ('income', 'expense')),
  amount_paise bigint not null check (amount_paise > 0),
  category_id text not null,
  date date not null,
  payment_method text check (payment_method in ('upi', 'card', 'cash', 'bankTransfer', 'wallet', 'other')),
  counterparty text check (char_length(counterparty) <= 80),
  note text check (char_length(note) <= 500),
  origin text not null default 'manual'
    check (origin in ('manual', 'subscription', 'loanRepayment', 'loanDisbursement', 'pendingSettlement')),
  origin_ref_id text,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  -- A transaction's type always matches its category's type.
  foreign key (user_id, category_id, type) references public.categories (user_id, id, type),
  constraint transactions_origin_ref check ((origin = 'manual') = (origin_ref_id is null))
);
comment on table public.transactions is 'Completed cash movements recorded by the user (not payment instructions). Linked rows (origin <> manual) belong to the loan payment, settlement, disbursement or subscription that created them.';
create index transactions_user_date_idx on public.transactions (user_id, date desc, created_at desc, id);
create index transactions_user_category_date_idx on public.transactions (user_id, category_id, date);
create index transactions_user_origin_idx on public.transactions (user_id, origin, origin_ref_id) where origin <> 'manual';
create index transactions_user_sync_idx on public.transactions (user_id, sync_seq);

-- ---------------------------------------------------------------------------
-- Budgets
-- ---------------------------------------------------------------------------

create table public.budgets (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  category_id text not null,
  limit_paise bigint not null check (limit_paise > 0),
  status text not null default 'active' check (status in ('active', 'paused')),
  warning_threshold_bps integer not null default 8000 check (warning_threshold_bps between 5000 and 9500),
  note text check (char_length(note) <= 200),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  foreign key (user_id, category_id) references public.categories (user_id, id)
);
comment on table public.budgets is 'Monthly spending limits per expense category. Spending is derived from expense transactions; budgets hold no money.';
-- Only one active budget per category.
create unique index budgets_one_active_per_category on public.budgets (user_id, category_id) where status = 'active';

-- Earlier limits, so past months keep the limit they had (Budget.previousLimits).
create table public.budget_limit_changes (
  user_id uuid not null,
  budget_id text not null,
  until_month text not null check (until_month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  limit_paise bigint not null check (limit_paise > 0),
  primary key (user_id, budget_id, until_month),
  foreign key (user_id, budget_id) references public.budgets (user_id, id) on delete cascade
);
comment on table public.budget_limit_changes is 'Limit a budget had up to and including until_month (budget month key yyyy-MM).';

-- ---------------------------------------------------------------------------
-- Goals, emergency fund and their movements (earmarking, not spending)
-- ---------------------------------------------------------------------------

create table public.goals (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  name text not null check (char_length(name) between 1 and 50),
  category text not null
    check (category in ('travel', 'purchase', 'education', 'investment', 'home', 'vehicle', 'wedding', 'health', 'other')),
  target_paise bigint not null check (target_paise > 0),
  target_date date,
  planned_monthly_paise bigint check (planned_monthly_paise is null or planned_monthly_paise > 0),
  color_index smallint not null check (color_index between 0 and 63),
  status text not null default 'active' check (status in ('active', 'archived')),
  note text check (char_length(note) <= 500),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id)
);
comment on table public.goals is 'Savings goals. The saved amount is derived from savings_movements; it is never stored.';

create table public.emergency_plans (
  user_id uuid primary key references auth.users (id) on delete cascade,
  essential_monthly_paise bigint not null check (essential_monthly_paise >= 0),
  target_months smallint not null check (target_months between 1 and 24),
  target_override_paise bigint check (target_override_paise is null or target_override_paise > 0),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq')
);
comment on table public.emergency_plans is 'Emergency fund plan (target = essentials x months, or an override). Saved amount comes from savings_movements.';

create table public.savings_movements (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  bucket_type text not null check (bucket_type in ('goal', 'emergencyFund')),
  bucket_id text not null,
  kind text not null check (kind in ('contribution', 'withdrawal')),
  amount_paise bigint not null check (amount_paise > 0),
  date date not null,
  note text check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  -- Set only for goal movements, so goal movements reference a real goal.
  goal_id text generated always as (case when bucket_type = 'goal' then bucket_id end) stored,
  primary key (user_id, id),
  foreign key (user_id, goal_id) references public.goals (user_id, id) on delete cascade,
  constraint savings_movements_ef_bucket check (bucket_type = 'goal' or bucket_id = 'emergency_fund')
);
comment on table public.savings_movements is 'Allocations of existing cash to a goal or the emergency fund (contribution) or back (withdrawal). They change earmarked/available, never cash, income, spending or net worth.';
create index savings_movements_bucket_idx on public.savings_movements (user_id, bucket_type, bucket_id, date);

-- ---------------------------------------------------------------------------
-- Loans
-- ---------------------------------------------------------------------------

create table public.loans (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  name text not null check (char_length(name) between 1 and 60),
  counterparty text not null check (char_length(counterparty) between 1 and 80),
  direction text not null check (direction in ('borrowed', 'lent')),
  structure text not null check (structure in ('amortizing', 'interestOnly')),
  principal_paise bigint not null check (principal_paise > 0),
  rate_bps integer not null check (rate_bps between 0 and 6000),
  start_date date not null,
  first_due_date date not null,
  frequency text not null check (frequency in ('monthly', 'quarterly', 'halfYearly', 'yearly')),
  tenure_installments integer check (tenure_installments is null or tenure_installments between 1 and 480),
  maturity_date date,
  prepayment_strategy text not null default 'reduceTenure' check (prepayment_strategy in ('reduceTenure', 'reduceEmi')),
  status text not null default 'active' check (status in ('active', 'closed')),
  disbursement_transaction_id text,
  note text check (char_length(note) <= 500),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  foreign key (user_id, disbursement_transaction_id) references public.transactions (user_id, id),
  constraint loans_amortizing_tenure check (structure <> 'amortizing' or tenure_installments is not null)
);
comment on table public.loans is 'Money borrowed (liability) or lent (receivable): EMI or interest-only. Outstanding and schedule are derived from terms + loan_payments.';

create table public.loan_payments (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  loan_id text not null,
  kind text not null check (kind in ('installment', 'interest', 'principal')),
  date date not null,
  interest_paise bigint not null default 0 check (interest_paise >= 0),
  principal_paise bigint not null default 0 check (principal_paise >= 0),
  period_number integer check (period_number is null or period_number >= 1),
  transaction_id text,
  note text check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  foreign key (user_id, loan_id) references public.loans (user_id, id) on delete restrict,
  foreign key (user_id, transaction_id) references public.transactions (user_id, id),
  constraint loan_payments_positive check (interest_paise + principal_paise > 0)
);
comment on table public.loan_payments is 'Repayments recorded by the user (interest/principal split). Immutable history: changing loan terms never rewrites them.';
create index loan_payments_loan_idx on public.loan_payments (user_id, loan_id, date);
-- At most one payment record per transaction.
create unique index loan_payments_transaction_key on public.loan_payments (user_id, transaction_id) where transaction_id is not null;

-- ---------------------------------------------------------------------------
-- Subscriptions (expected recurring expenses; projections, not spending)
-- ---------------------------------------------------------------------------

create table public.subscriptions (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  name text not null check (char_length(name) between 1 and 60),
  amount_paise bigint not null check (amount_paise > 0),
  category_id text not null,
  frequency text not null check (frequency in ('weekly', 'monthly', 'quarterly', 'halfYearly', 'yearly')),
  next_due_date date not null,
  start_date date,
  status text not null default 'active' check (status in ('active', 'paused', 'cancelled')),
  auto_renews boolean not null default true,
  payment_method text check (payment_method in ('upi', 'card', 'cash', 'bankTransfer', 'wallet', 'other')),
  note text check (char_length(note) <= 500),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  foreign key (user_id, category_id) references public.categories (user_id, id)
);
comment on table public.subscriptions is 'Expected recurring charges. A renewal date passing is not spending; only "mark paid" records a linked expense.';

-- ---------------------------------------------------------------------------
-- Pending payments (obligations to/from other people) and settlements
-- ---------------------------------------------------------------------------

create table public.pending_payments (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  counterparty text not null check (char_length(counterparty) between 1 and 60),
  direction text not null check (direction in ('iOwe', 'owedToMe')),
  kind text not null check (kind in ('borrowed', 'lent', 'sharedExpense', 'reimbursement', 'other')),
  original_paise bigint not null check (original_paise > 0),
  purpose text not null check (char_length(purpose) between 1 and 120),
  created_date date not null,
  notes text check (char_length(notes) <= 500),
  is_cancelled boolean not null default false,
  -- Shared with another FiNN user (double entry). Stored once, under the
  -- creator; the other person sees a derived, reversed view (id mir_<shared_id>).
  shared_id text,
  shared_with_user_id uuid references auth.users (id) on delete set null,
  shared_with_handle text,
  -- Bill split this item is part of.
  split_id text,
  split_method text check (split_method in ('equally', 'exact', 'percent', 'shares', 'adjustment')),
  split_includes_me boolean,
  split_my_share_paise bigint check (split_my_share_paise is null or split_my_share_paise >= 0),
  split_part integer,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  constraint pending_shared_pair check ((shared_id is null) = (shared_with_handle is null)),
  constraint pending_split_fields check ((split_id is null) = (split_method is null))
);
comment on table public.pending_payments is 'Obligations the user owes or is owed (record-keeping only). Outstanding = original - settlements; creating one never changes cash.';
create unique index pending_payments_shared_key on public.pending_payments (shared_id) where shared_id is not null;
create index pending_payments_shared_with_idx on public.pending_payments (shared_with_user_id) where shared_with_user_id is not null;
create index pending_payments_user_sync_idx on public.pending_payments (user_id, sync_seq);

create table public.pending_settlements (
  -- The person who recorded the settlement (owner of the row and of its
  -- optional linked transaction).
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  pending_owner_id uuid not null,
  pending_id text not null,
  -- Copied from the pending item (immutable) so both parties can be resolved
  -- even while the item is being deleted.
  shared_with_user_id uuid,
  amount_paise bigint not null check (amount_paise > 0),
  date date not null,
  method text check (method in ('upi', 'card', 'cash', 'bankTransfer', 'wallet', 'other')),
  transaction_id text,
  note text check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id),
  foreign key (pending_owner_id, pending_id) references public.pending_payments (user_id, id) on delete cascade,
  foreign key (user_id, transaction_id) references public.transactions (user_id, id)
);
comment on table public.pending_settlements is 'Full or partial settlements of a pending item, recorded by either party. The optional linked transaction belongs to the recorder only.';
create index pending_settlements_pending_idx on public.pending_settlements (pending_owner_id, pending_id);
create index pending_settlements_shared_idx on public.pending_settlements (shared_with_user_id) where shared_with_user_id is not null;
create unique index pending_settlements_transaction_key on public.pending_settlements (user_id, transaction_id) where transaction_id is not null;

-- ---------------------------------------------------------------------------
-- Assets (user-entered valuations for net worth)
-- ---------------------------------------------------------------------------

create table public.assets (
  user_id uuid not null references auth.users (id) on delete cascade,
  id text not null check (char_length(id) between 1 and 64),
  name text not null check (char_length(name) between 2 and 40),
  type text not null check (type in ('bankDeposit', 'investment', 'retirement', 'gold', 'property', 'vehicle', 'other')),
  value_paise bigint not null check (value_paise >= 0),
  valued_on date not null,
  note text check (char_length(note) <= 500),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, id)
);
comment on table public.assets is 'User-entered asset valuations. Cash tracked in FiNN is never also an asset.';

-- ---------------------------------------------------------------------------
-- Alert inbox (read / dismissed state of derived alerts)
-- ---------------------------------------------------------------------------

create table public.alert_inbox (
  user_id uuid not null references auth.users (id) on delete cascade,
  alert_key text not null check (char_length(alert_key) between 1 and 200),
  read_at timestamptz,
  dismissed_at timestamptz,
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  primary key (user_id, alert_key)
);
comment on table public.alert_inbox is 'Read/dismissed state for alerts. Alerts themselves are derived deterministically; keys are type + record + period.';

-- ---------------------------------------------------------------------------
-- Operations: idempotency, audit, sync tombstones
-- ---------------------------------------------------------------------------

create table public.idempotency_keys (
  user_id uuid not null references auth.users (id) on delete cascade,
  key text not null check (char_length(key) between 8 and 128),
  action_id text not null,
  request_fingerprint text not null,
  response jsonb not null,
  created_at timestamptz not null default now(),
  primary key (user_id, key)
);
comment on table public.idempotency_keys is 'Completed action requests. A repeated key replays the stored response; a key reused for a different request is rejected. Written in the same transaction as the operation, so failed attempts leave no key.';
create index idempotency_keys_created_idx on public.idempotency_keys (created_at);

create table public.audit_log (
  user_id uuid not null references auth.users (id) on delete cascade,
  id bigint generated always as identity,
  action_id text not null,
  summary text not null,
  channel text not null check (channel in ('ui', 'agent', 'voice', 'import', 'system')),
  confirmed_by text,
  succeeded boolean not null,
  failure_code text,
  failure_message text,
  record_ids text[] not null default '{}',
  at timestamptz not null default now(),
  primary key (user_id, id)
);
comment on table public.audit_log is 'Every attempted operation (successful or failed), with channel and confirmation. Contains summaries, never tokens or secrets.';
create index audit_log_user_at_idx on public.audit_log (user_id, at desc);

create table public.deleted_records (
  user_id uuid not null references auth.users (id) on delete cascade,
  collection text not null,
  record_id text not null,
  sync_seq bigint not null default nextval('public.finn_sync_seq'),
  deleted_at timestamptz not null default now(),
  primary key (user_id, collection, record_id, sync_seq)
);
comment on table public.deleted_records is 'Tombstones so clients can remove deleted records during incremental sync.';
create index deleted_records_sync_idx on public.deleted_records (user_id, sync_seq);

-- ---------------------------------------------------------------------------
-- Triggers: bump sync_seq on update, write tombstones on delete
-- ---------------------------------------------------------------------------

create function private.bump_sync_seq() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.sync_seq := nextval('public.finn_sync_seq');
  return new;
end $$;

-- Tombstone for the row owner (and, for shared pending data, the other party,
-- who sees the record under a mir_ id).
create function private.record_tombstone() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  coll text := tg_argv[0];
  other_user uuid;
  other_id text;
begin
  -- Account deletion cascades through every table: only users that still
  -- exist get tombstones.
  if exists (select 1 from auth.users where id = old.user_id) then
    insert into public.deleted_records (user_id, collection, record_id) values (old.user_id, coll, old.id);
  end if;
  if coll = 'pending' then
    other_user := old.shared_with_user_id;
    other_id := 'mir_' || old.shared_id;
  elsif coll = 'settlements' then
    -- Recorder sees the raw id; the other party sees mir_<id>.
    other_user := case when old.pending_owner_id <> old.user_id then old.pending_owner_id else old.shared_with_user_id end;
    other_id := 'mir_' || old.id;
  end if;
  if other_user is not null and exists (select 1 from auth.users where id = other_user) then
    insert into public.deleted_records (user_id, collection, record_id) values (other_user, coll, other_id);
  end if;
  return old;
end $$;
revoke all on function private.record_tombstone() from public, anon, authenticated;

do $$
declare
  t record;
begin
  for t in
    select * from (values
      ('profiles', null), ('user_preferences', null), ('categories', 'categories'), ('transactions', 'transactions'),
      ('budgets', 'budgets'), ('goals', 'goals'), ('emergency_plans', null), ('savings_movements', 'savings_movements'),
      ('loans', 'loans'), ('loan_payments', 'loan_payments'), ('subscriptions', 'subscriptions'),
      ('pending_payments', 'pending'), ('pending_settlements', 'settlements'), ('assets', 'assets'),
      ('alert_inbox', null)
    ) as v(tbl, coll)
  loop
    execute format('create trigger %I before update on public.%I for each row execute function private.bump_sync_seq()',
                   t.tbl || '_bump_sync_seq', t.tbl);
    if t.coll is not null then
      execute format('create trigger %I after delete on public.%I for each row execute function private.record_tombstone(%L)',
                     t.tbl || '_tombstone', t.tbl, t.coll);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
-- The Next.js API runs every request inside a transaction with
-- `set local role authenticated` and the caller's JWT claims, so these
-- policies apply to the API as well as to any direct client access.

-- Pending items the caller may see: own items, or items shared with them.
create function private.can_access_pending(owner uuid, pending text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.pending_payments p
    where p.user_id = owner and p.id = pending
      and (p.user_id = (select auth.uid()) or p.shared_with_user_id = (select auth.uid()))
  );
$$;
revoke all on function private.can_access_pending(uuid, text) from public, anon;
grant execute on function private.can_access_pending(uuid, text) to authenticated;

do $$
declare
  tbl text;
begin
  foreach tbl in array array[
    'profiles', 'user_preferences', 'categories', 'transactions', 'budgets', 'budget_limit_changes', 'goals',
    'emergency_plans', 'savings_movements', 'loans', 'loan_payments', 'subscriptions', 'assets', 'alert_inbox',
    'idempotency_keys', 'audit_log', 'deleted_records', 'pending_payments', 'pending_settlements'
  ]
  loop
    execute format('alter table public.%I enable row level security', tbl);
    execute format('revoke all on public.%I from anon', tbl);
  end loop;

  -- Plain owner-only tables.
  foreach tbl in array array[
    'user_preferences', 'categories', 'transactions', 'budgets', 'budget_limit_changes', 'goals',
    'emergency_plans', 'savings_movements', 'loans', 'loan_payments', 'subscriptions', 'assets', 'alert_inbox',
    'idempotency_keys'
  ]
  loop
    execute format($p$create policy %I on public.%I for all to authenticated
                     using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id)$p$,
                   tbl || '_owner', tbl);
  end loop;
end $$;

-- Profiles: own row only. Other users are visible through
-- private.search_users / private.directory_entries (name, handle, phone hint).
create policy profiles_owner on public.profiles for all to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

-- Audit log and tombstones are append/read only for the owner.
create policy audit_log_read on public.audit_log for select to authenticated using ((select auth.uid()) = user_id);
create policy audit_log_insert on public.audit_log for insert to authenticated with check ((select auth.uid()) = user_id);
create policy deleted_records_read on public.deleted_records for select to authenticated using ((select auth.uid()) = user_id);
create policy deleted_records_insert on public.deleted_records for insert to authenticated with check ((select auth.uid()) = user_id);

-- Pending items: the creator owns the row; the person it is shared with can
-- read it and update it (settlement bookkeeping, write-off when they are owed).
-- The API decides which fields each party may change.
create policy pending_select on public.pending_payments for select to authenticated
  using ((select auth.uid()) = user_id or (select auth.uid()) = shared_with_user_id);
create policy pending_insert on public.pending_payments for insert to authenticated
  with check ((select auth.uid()) = user_id);
create policy pending_update on public.pending_payments for update to authenticated
  using ((select auth.uid()) = user_id or (select auth.uid()) = shared_with_user_id)
  with check ((select auth.uid()) = user_id or (select auth.uid()) = shared_with_user_id);
create policy pending_delete on public.pending_payments for delete to authenticated
  using ((select auth.uid()) = user_id);

-- Settlements: visible to both parties; recorded by either party on an item
-- they can access; removed only together with the item (cascade).
create policy settlements_select on public.pending_settlements for select to authenticated
  using ((select auth.uid()) in (user_id, pending_owner_id, shared_with_user_id));
create policy settlements_insert on public.pending_settlements for insert to authenticated
  with check ((select auth.uid()) = user_id and private.can_access_pending(pending_owner_id, pending_id));

-- ---------------------------------------------------------------------------
-- Directory functions (never expose more than name, handle, phone hint)
-- ---------------------------------------------------------------------------

create function private.search_users(query text, max_results integer default 10)
returns table (user_id uuid, display_name text, handle text, phone_hint text)
language sql stable security definer set search_path = '' as $$
  select p.user_id, p.display_name, p.handle, p.phone_hint
  from public.profiles p
  where (select auth.uid()) is not null
    and char_length(trim(query)) >= 2
    and p.user_id <> (select auth.uid())
    and (p.handle ilike '%' || replace(replace(replace(trim(query), '\', '\\'), '%', '\%'), '_', '\_') || '%'
         or p.display_name ilike '%' || replace(replace(replace(trim(query), '\', '\\'), '%', '\%'), '_', '\_') || '%')
  order by p.display_name, p.handle
  limit least(greatest(max_results, 1), 20);
$$;
revoke all on function private.search_users(text, integer) from public, anon;
grant execute on function private.search_users(text, integer) to authenticated;

create function private.directory_entries(ids uuid[])
returns table (user_id uuid, display_name text, handle text, phone_hint text)
language sql stable security definer set search_path = '' as $$
  select p.user_id, p.display_name, p.handle, p.phone_hint
  from public.profiles p
  where (select auth.uid()) is not null and p.user_id = any (ids);
$$;
revoke all on function private.directory_entries(uuid[]) from public, anon;
grant execute on function private.directory_entries(uuid[]) to authenticated;
